#define DIM 128
#define DIM_M_1 (DIM - 1)
#define WORLD_DIMENSIONS ivec2(1<<29, 1<<28)
#define ZOOM 1.0
#define H_DIM (DIM >> 1)
#define SHOW_WRAP

#define IMOD(n, d) ((n) - ((n) / (d)) * (d))

// CMD OPT J
