mat2 r2(in float a){ float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }

uint uhash12(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

vec4 unpack_colour(uint colour) {
    return vec4((colour >> 24) & 0xFFu, (colour >> 16) & 0xFFu, (colour >> 8) & 0xFFu, colour & 0xFFu) / 255.0f;
}

void mainImage(out vec4 colour, in vec2 coord) {

    ivec2 xz = ivec2(coord);

#ifdef SHOW_WRAP
    xz -= (ivec2(iResolution.xy) >> 1);
#endif

    if (xz.x < 0) xz.x = WORLD_DIMENSIONS.x + xz.x;
    if (xz.y < 0) xz.y = WORLD_DIMENSIONS.y + xz.y;

    ivec2 cid = xz / DIM;
    ivec2 cuv = xz & DIM_M_1;

    ivec2 p = xz;

    ivec2 s1 = ivec2(1, 4);
    ivec2 s2 = ivec2(1, 7);

    p.y = (p.y * 4 / 7);

    ivec2 p2 = p * ivec2(1, 2);

    ivec4 id = ivec4(p2 - (p & DIM_M_1), p2 - ((p + H_DIM) & DIM_M_1)) & ~DIM_M_1;    
    ivec4 fl = ivec4(p & ~DIM_M_1, (p + H_DIM) & ~DIM_M_1);

    ivec4 h1 = ivec4((p - fl.xy - H_DIM) * s2 / s1, id.xy);
    ivec4 h2 = ivec4((p - fl.zw) * s2 / s1, id.zw);

    float d1 = dot(vec2(h1), vec2(h1));
    float d2 = dot(vec2(h2), vec2(h2));

    ivec4 h = d1 < d2 ? h1 : h2;
    h.zw &= (WORLD_DIMENSIONS - 1);

    uint hash = uhash12(uvec2(h.zw));
    vec3 col = unpack_colour(hash).xyz;

    vec2 read = vec2(h) / float(DIM);

    float fhash = uintBitsToFloat(hash & 0x007fffffu | 0x3f800000u) - 1.0f;

    float rot_degrees = float(IMOD(hash, 6u)) * 60.0f;
    read = r2(radians(rot_degrees)) * read;

    read = read * 0.865f + 0.5f;

    vec3 sampled = vec3(texture(iChannel0, read).rgb);

    col = max(col, sampled);

    colour = vec4(col, 0.0f);
}
